from sqlalchemy import inspect, text
from sqlalchemy.sql.elements import quoted_name

@app.get("/debug/db-check")
async def debug_db_check():
    try:
        if not db_engine:
            return {"error": "DB Engine Not Initialized"}

        inspector = inspect(db_engine)
        tables = inspector.get_table_names(schema="public")
        data_counts = {}

        with db_engine.connect() as conn:
            for table in tables:
                # 허용된 테이블명만 사용하고, 식별자는 반드시 quote 처리
                safe_table = quoted_name(table, quote=True)
                res = conn.execute(text(f'SELECT count(*) FROM {safe_table}')).fetchone()
                data_counts[table] = res[0]

        return {"tables": tables, "counts": data_counts}
    except Exception as e:
        return {"error": str(e)}

